import{_ as a,o as n,a as p,b as t}from"./app.DII24pJb.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"基础定义","link":"/api/SIMD-API/c_api/defs/defs"},{"text":"枚举","link":"/api/SIMD-API/c_api/defs/enum/enum"},{"text":"asc_channel_pad_mode","link":"/api/SIMD-API/c_api/defs/enum/asc_channel_pad_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/defs/enum/asc_channel_pad_mode.md","filePath":"api/SIMD-API/c_api/defs/enum/asc_channel_pad_mode.md","outlineHeaders":[{"level":2,"title":"枚举类具体定义","slug":"枚举类具体定义","link":"#枚举类具体定义"},{"level":2,"title":"枚举值详解","slug":"枚举值详解","link":"#枚举值详解"}],"lastUpdated":1789543187000}'),c={name:"api/SIMD-API/c_api/defs/enum/asc_channel_pad_mode.md"};function d(l,s,e,_,i,o){return n(),p("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>asc_channel_pad_mode</h1><p>头文件路径为：<code>&quot;c_api/defs/enum.h&quot;</code>。</p><p>asc_channel_pad_mode用于表示从GM搬运到L1 Buffer时，每个32字节通道块的填充或压缩模式，可用于<a href="../../cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1</a>高维切分数据搬运接口。该模式为硬件<code>pad_func_mode</code>的类型化定义，对每个32字节通道数据块生效，取值范围为[0, 8]。</p><p><code>EXPAND_*</code>为填充模式，在目的数据中插入padding值。通道填充值通过<a href="../../cube_datamove/asc_set_gm2l1_padding.html">asc_set_gm2l1_padding</a>设置。</p><p><code>COMPACT_*</code>为删除模式，从每个32字节源数据块中移除高位部分数据，仅保留低位有效区域。</p><p>该枚举控制的是通道块内部的填充或删除，区别于通过<a href="../../cube_datamove/asc_set_gm2l1_pad.html">asc_set_gm2l1_pad</a>配置的左右填充。</p><h2 id="枚举类具体定义">枚举类具体定义<a class="header-anchor" href="#枚举类具体定义">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">asc_channel_pad_mode</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">NONE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">EXPAND_1B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">EXPAND_2B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="n">EXPAND_4B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span>
<span class="w">    </span><span class="n">EXPAND_8B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span>
<span class="w">    </span><span class="n">EXPAND_16B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span>
<span class="w">    </span><span class="n">COMPACT_4B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span>
<span class="w">    </span><span class="n">COMPACT_8B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">7</span><span class="p">,</span>
<span class="w">    </span><span class="n">COMPACT_16B</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span>
<span class="p">};</span>
</code></pre></div><h2 id="枚举值详解">枚举值详解<a class="header-anchor" href="#枚举值详解">​</a></h2><p><strong>表1</strong> 枚举值说明</p><table><thead><tr><th>枚举值</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td>NONE</td><td>0</td><td>不执行通道填充或压缩。</td></tr><tr><td>EXPAND_1B</td><td>1</td><td>每1字节源数据后插入31字节填充值，其中插入的每个padding的位宽为b8。</td></tr><tr><td>EXPAND_2B</td><td>2</td><td>每2字节源数据后插入15个填充值，其中插入的每个padding的位宽为b16。</td></tr><tr><td>EXPAND_4B</td><td>3</td><td>每4字节源数据后插入14个填充值，其中插入的每个padding的位宽为b16。</td></tr><tr><td>EXPAND_8B</td><td>4</td><td>每8字节源数据后插入12个填充值，其中插入的每个padding的位宽为b16。</td></tr><tr><td>EXPAND_16B</td><td>5</td><td>每16字节源数据后插入8个填充值，其中插入的每个padding的位宽为b16。</td></tr><tr><td>COMPACT_4B</td><td>6</td><td>每32字节源数据保留低4字节，丢弃高28字节，只保留4个最低有效位字节。</td></tr><tr><td>COMPACT_8B</td><td>7</td><td>每32字节源数据保留低8字节，丢弃高24字节，只保留8个最低有效位字节。</td></tr><tr><td>COMPACT_16B</td><td>8</td><td>每32字节源数据保留低16字节，丢弃高16字节，只保留16个最低有效位字节。</td></tr></tbody></table></article></div>`,1)])])}const m=a(c,[["render",d]]);export{h as __pageData,m as default};
